mapper.insert:
INSERT INTO reviews (
animation_id, user_id, rating, content, like_count, is_spoiler, created_at
) VALUES (
#{animationId}, #{userId}, #{rating}, #{content}, 0, #{isSpoiler}, NOW()
)

mapper.update:
UPDATE reviews
SET like_count = like_count + #{delta}
WHERE review_id = #{reviewId}

UPDATE reviews
SET is_spoiler = #{isSpoiler}
WHERE review_id = #{reviewId}

UPDATE reviews
SET deleted_at = NOW()
WHERE review_id = #{reviewId}

mapper.select:
SELECT COUNT(*) > 0
FROM reviews
WHERE animation_id = #{animationId}
AND user_id = #{userId}
AND deleted_at IS NULL
